@Component
public class DatabaseHealthIndicator implements HealthIndicator {
    private final DataSource dataSource;

    public DatabaseHealthIndicator(DataSource ds) {
        this.dataSource = ds;
    }

    @Override
    public Health health() {
        try (Connection c = dataSource.getConnection()) {
            return Health.up()
                .withDetail("database", "accessible")
                .withDetail("version", c.getMetaData().getDatabaseProductVersion())
                .build();
        } catch (SQLException e) {
            return Health.down()
                .withDetail("database", e.getMessage())
                .build();
        }
    }
}

@Component
public class CustomMetrics {
    private final MeterRegistry registry;

    public CustomMetrics(MeterRegistry registry) {
        this.registry = registry;
    }

    public void registrarPedido(String tipo) {
        registry.counter("pedidos.total", "tipo", tipo).increment();
    }

    public void registrarTiempoProcesamiento(Duration duracion) {
        registry.timer("pedidos.duracion").record(duracion);
    }

    public void registrarCola(int tamanio) {
        registry.gauge("pedidos.cola", tamanio);
    }
}

@Endpoint(id = "cache-stats")
public class CacheStatsEndpoint {
    private long hitCount = 0;
    private long missCount = 0;

    @ReadOperation
    public Map<String, Object> stats() {
        double hitRate = hitCount == 0 ? 0.0
            : (double) hitCount / (hitCount + missCount);
        return Map.of(
            "hits", hitCount,
            "misses", missCount,
            "hitRate", hitRate
        );
    }

    @WriteOperation
    public void resetStats() {
        hitCount = 0;
        missCount = 0;
    }
}

